      "compare": "双循环为每个位置重算乘积；前后缀复用相邻位置的大量共同乘积。把左乘积直接存在答案里，还能省下一份前缀数组。",
      "question": "数组含两个0时结果是什么？",
      "answer": "全部为0，因为排除任何一个位置后仍至少剩一个0。前后缀法不用写特殊分支也会得到这个结果。"
