    "slug": "flatten-binary-tree-to-linked-list",
    "level": "中等",
    "category": "二叉树",
    "summary": "原地把二叉树改成仅使用右指针的链，节点顺序等于原树前序遍历。",
    "example": "树1(左2(左3),右4) → 1→2→3→4",
