    "url": "https://leetcode.cn/problems/flatten-binary-tree-to-linked-list/",
    "teaching": {
      "why": "前序要求当前根后面先接整棵左子树，再接原右子树。可以先把左子树整体插入根与右子树之间，之后沿右链继续展开；不必一次把整棵左树彻底拉平。",
      "state": "cur：当前节点；pred：cur左子树沿right走到的最右节点；原右子树先接到pred.right。",
      "walk": [
        "树1有左2、右4，2有左3",
        "在1处，左子树最右节点是2，把4接到2.right",
        "令1.right=2、1.left=null",
        "走到2，它的左子树只有3，于是把原右4接到3.right，再让2.right=3并清空left",
        "得到1→2→3→4。"
      ],
      "proof": "左子树最终展开后的所有节点都应位于原右子树之前。把右子树暂接到左子树的最右通道，不会丢失它；后续局部展开会继续把未处理的左分支插到它之前。",
      "cost": "每节点随cur访问一次，寻找前驱的右边沿原结构摊还只被扫描常数次，总O(n)。几个指针O(1)，输出复用原节点。",
      "compare": "先保存前序节点数组再连线最清楚；原地版本把这个访问顺序直接编码成局部指针重接，省去数组。",
      "question": "为什么一定要先连接pred.right，再覆盖cur.right？",
      "answer": "否则原右子树入口会被左子树覆盖而丢失。指针修改顺序的首要原则是先保留仍需访问的部分。"
    }
