      "cost": "长度L的操作最多走L条边，O(L)，固定字母表或期望常数映射查询下成立。总节点数不超过所有插入单词字符总数加1。",
      "compare": "列表扫描查询与字典单词数相关；Trie查询主要由查询词自身长度决定。代价是节点和孩子映射的对象开销，短字典未必比哈希更划算。",
      "question": "先插入cat，再插入ca，会发生什么？",
