      "cost": "一遍O(n)，两个状态O(1)。暴力枚举约n(n-1)/2对为O(n²)，优化掉的是针对同一卖出日的买入日期搜索。",
      "compare": "先理解“给定卖出日怎样选买入日”，自然导出前缀最小值。不能用全数组最大减最小，因为时间顺序可能反过来。",
      "question": "价格一直下跌时为什么返回0？",
      "answer": "可以不交易。所有先买后卖收益都为负，profit初始0且只取更大值，保留不交易方案。"
