      "proof": "扫描到i时，如果i>far，所有此前可达位置都无法跨过这个缺口，后面位置也不可能被访问；反之i可达，其跳跃范围都可以安全加入。",
      "cost": "每个位置至多检查一次，O(n)。只保存far与下标O(1)。显式DP把每个可达位置的所有跳转逐一标记，最坏O(n²)。",
      "compare": "贪心保存的是可达性摘要，不是每次真的选择最远落点。把两者混淆会以为必须沿某条单独的贪心路线行走。",
      "question": "遇到0是否一定失败？",
