    "summary": "数组保证能够到达末尾，求从起点到末尾所需的最少跳跃次数。",
    "example": "[2,3,1,1,4] → 2次",
    "pitfall": "扫描到当前层边界才增加跳数；不处理最后一个位置，避免多计一次。",
